  sum += i;
}

document.body.append('сумма 1..5 = ' + sum);

const cities = ['Псков', 'Казань', 'Омск'];
let line = '';

for (const city of cities) {
  line += city + ' ';
}

for (const letter of 'кот') {
  line += letter.toUpperCase();
}

document.body.append(line);

let balance = 100;
let attempts = 0;

while (true) {
  balance -= 30;
  attempts++;
  if (balance < 20) break; // выходим, когда остаток стал мал
}

document.body.append('списаний: ' + attempts + ', остаток: ' + balance);

