exercises.starter:
function sumTo(n) {
  let total = 0;
  /* цикл от 1 до n включительно */
  return total;
}

exercises.solution:
function sumTo(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) {
    total += i;
  }
  return total;
}

