function countEvens(numbers) {
  let count = 0;
  /* for...of по массиву + проверка на чётность */
  return count;
}

exercises.solution:
function countEvens(numbers) {
  let count = 0;
  for (const n of numbers) {
    if (n % 2 === 0) {
      count++;
    }
  }
  return count;
}
